#!/usr/bin/env node
/**
 * Every class this plugin uses must exist in the HOST app's compiled stylesheet.
 *
 * A plugin bundle is JavaScript only — `makePluginConfig.mjs` emits one ESM
 * file and no CSS — so the UI is styled entirely by the host's already-built
 * Tailwind sheet. That sheet is generated by scanning the host's own `src/**`,
 * which never includes this repo (the plugin is fetched at runtime from a URL).
 * A class written only here lands in the DOM with no rule behind it, silently.
 *
 * `npm test` guards the part that can be checked offline (arbitrary values —
 * see ui/hostCssClasses.test.ts). This script does the complete check against
 * a real host build, which is the only ground truth:
 *
 *   # in the host checkout
 *   npm run build
 *   # back here
 *   node scripts/check-host-classes.mjs ../developer-desktop-utils/dist/assets/*.css
 *
 * Run it against the OLDEST host release you still support, not just the tip:
 * the host added a safelist for plugins (`src/styles/plugin-utilities.css`),
 * but a plugin installs into whatever host the user already has.
 */
import fs from 'node:fs';
import path from 'node:path';

const cssFiles = process.argv.slice(2);
if (cssFiles.length === 0) {
  console.error('usage: check-host-classes.mjs <host dist/assets/*.css ...>');
  process.exit(2);
}
const css = cssFiles.map((f) => fs.readFileSync(f, 'utf8')).join('\n');

const cache = new Map();
/** Tailwind escapes every char outside [A-Za-z0-9_-], so a class's compiled
 *  selector is derivable and can be searched for verbatim. */
function isShipped(token) {
  if (!cache.has(token)) {
    const selector = '.' + [...token].map((c) => (/[A-Za-z0-9_-]/.test(c) ? c : '\\' + c)).join('');
    cache.set(token, css.includes(selector));
  }
  return cache.get(token);
}

function sources(dir, out = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (['node_modules', 'dist', '.git', 'sidecar', 'target'].includes(entry.name)) continue;
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) sources(p, out);
    else if (/\.tsx$/.test(p) && !/\.test\.tsx$/.test(p)) out.push(p);
  }
  return out;
}

const stripComments = (s) => s.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '');

/** The balanced `{…}` or `"…"` after a `className=`, plus any standalone
 *  `cn(…)` call — so ordinary identifiers never masquerade as class names. */
function classExpressions(src) {
  const out = [];
  for (const m of src.matchAll(/\bclassName\s*=\s*/g)) {
    const i = m.index + m[0].length;
    if (src[i] === '"' || src[i] === "'") {
      out.push([JSON.stringify(src.slice(i + 1, src.indexOf(src[i], i + 1))), i + 1]);
    } else if (src[i] === '{') {
      let depth = 0, j = i;
      for (; j < src.length; j++) {
        if (src[j] === '{') depth++;
        else if (src[j] === '}' && --depth === 0) break;
      }
      out.push([src.slice(i + 1, j), i]);
    }
  }
  for (const m of src.matchAll(/\bcn\s*\(/g)) {
    let depth = 0, j = m.index + m[0].length - 1;
    for (; j < src.length; j++) {
      if (src[j] === '(') depth++;
      else if (src[j] === ')' && --depth === 0) break;
    }
    out.push([src.slice(m.index, j), m.index]);
  }
  return out;
}

const VARIANT = /^(?:[a-z-]+(?:\[[^\]]*\])?:)+/;
const ARBITRARY = /-?\[[^\]]*\]$/;
const UTILITY = /^-?[a-z][a-z0-9]*(?:[-./][a-z0-9.%]+)*$/;
/** A dashless word inside cn() is nearly always a value being compared
 *  (`l.stream === 'stderr'`), not a class — only these are really classes. */
const BARE = new Set([
  'flex', 'grid', 'block', 'inline', 'hidden', 'contents', 'table', 'isolate',
  'relative', 'absolute', 'fixed', 'sticky', 'static', 'visible', 'invisible',
  'truncate', 'italic', 'underline', 'uppercase', 'lowercase', 'capitalize',
  'border', 'rounded', 'shadow', 'transition', 'container', 'group', 'peer',
  'resize', 'appearance-none', 'antialiased',
]);

const missing = new Map();
for (const file of sources(path.resolve(import.meta.dirname, '..', 'plugins'))) {
  const src = stripComments(fs.readFileSync(file, 'utf8'));
  for (const [expr, at] of classExpressions(src)) {
    for (const literal of expr.matchAll(/'([^'\n]*)'|"([^"\n]*)"|`([^`\n${}]*)`/g)) {
      for (const token of (literal[1] ?? literal[2] ?? literal[3] ?? '').trim().split(/\s+/)) {
        if (!token) continue;
        const head = token.replace(VARIANT, '').replace(ARBITRARY, '');
        if (head !== '' && !UTILITY.test(head)) continue;   // not a class, skip
        if (!head.includes('-') && !head.includes('/') && !BARE.has(head)) continue;
        if (isShipped(token)) continue;
        const line = src.slice(0, at + literal.index).split('\n').length;
        if (!missing.has(token)) missing.set(token, new Set());
        missing.get(token).add(`${path.relative(process.cwd(), file)}:${line}`);
      }
    }
  }
}

if (missing.size === 0) {
  console.log(`OK — every class resolves in ${cssFiles.length} host stylesheet(s).`);
  process.exit(0);
}
console.error('Classes with no rule in the host stylesheet:\n');
for (const [cls, where] of [...missing].sort()) {
  console.error(`  ${cls.padEnd(42)} ${[...where].join(', ')}`);
}
console.error(`
${missing.size} class(es). Each renders as nothing at all. Use an inline
\`style\` for the value, or pick a class the host already ships.

A few may be false positives — a string that is not a class list but sits
inside a cn() call. Check before changing anything.`);
process.exit(1);
